// Temporal Workflow Definition for Order Saga
@WorkflowInterface
public interface OrderSagaWorkflow {
    @WorkflowMethod
    void executeOrder(OrderRequest request);
}

public class OrderSagaImpl implements OrderSagaWorkflow {
    private final PaymentActivity payment = Workflow.newActivityStub(PaymentActivity.class);
    private final InventoryActivity inventory = Workflow.newActivityStub(InventoryActivity.class);
    @Override
    public void executeOrder(OrderRequest req) {
        inventory.reserve(req.itemId());
        payment.charge(req.amount()); // Automatically retries with exponential backoff
    }
}

